import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"Class: GenerationScheduler<TChunk>","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/chunkgen/classes/GenerationScheduler.md","filePath":"api/@jsprismarine/chunkgen/classes/GenerationScheduler.md"}`),a={name:`api/@jsprismarine/chunkgen/classes/GenerationScheduler.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/chunkgen</a> / GenerationScheduler</p><h1 id="class-generationscheduler-tchunk" tabindex="-1">Class: GenerationScheduler&lt;TChunk&gt; <a class="header-anchor" href="#class-generationscheduler-tchunk" aria-label="Permalink to “Class: GenerationScheduler&lt;TChunk&gt;”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/7418be10dd694d6bb5f284896ea80cab1efdb551/packages/chunkgen/src/GenerationScheduler.ts#L66" target="_blank" rel="noreferrer">GenerationScheduler.ts:66</a></p><p>Drives chunks up the ladder, one layer of the neighborhood at a time.</p><p>Java&#39;s <code>ChunkGenerationTask.runUntilWait</code>, with one run per call to <a href="#generate">generate</a>. To bring a chunk to a status, the neighborhood has to reach that status&#39;s dependencies first, so the run walks the ladder from <code>empty</code> upward and at each rung applies the step to the square of chunks the accumulated dependency table sizes. Driving one chunk to <code>terrain</code> is therefore five layers at radii 9, 9, 1, 1 and 0, and driving one to <code>full</code> is ten at 11, 11, 3, 3, 2, 1, 1, 0, 0, 0.</p><p>Concurrent runs share work rather than duplicate it, because a holder keeps one promise per status and the second run to reach a rung awaits the first run&#39;s promise. Nine chunks asked for at once build terrain over the union of their windows, not over nine separate windows: at a <code>full</code> target that is 49 terrain bodies rather than 225.</p><p>The result does not depend on the order runs arrive or how many are outstanding. Every body reads through <a href="./StepRegion.html">StepRegion</a>, which refuses an input the step table did not declare, and nothing re-enters a rung, so a status&#39;s inputs are the same set whichever run happened to create its promise.</p><p>Each run acquires its whole neighborhood before it runs a step and releases it at the end, including when a body throws. A caller that needs the chunk to stay resident afterwards acquires its own reference on the holder first; otherwise the holders are dropped and the returned <a href="./ProtoChunk.html">ProtoChunk</a> is all that survives.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="tchunk" tabindex="-1">TChunk <a class="header-anchor" href="#tchunk" aria-label="Permalink to “TChunk”">​</a></h3><p><code>TChunk</code> <em>extends</em> <a href="./../#stagedchunk"><code>StagedChunk</code></a> = <a href="./ProtoChunk.html"><code>ProtoChunk</code></a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new GenerationScheduler</strong>&lt;<code>TChunk</code>&gt;(<code>options</code>): <code>GenerationScheduler</code>&lt;<code>TChunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/7418be10dd694d6bb5f284896ea80cab1efdb551/packages/chunkgen/src/GenerationScheduler.ts#L72" target="_blank" rel="noreferrer">GenerationScheduler.ts:72</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#generationscheduleroptions"><code>GenerationSchedulerOptions</code></a>&lt;<code>TChunk</code>&gt;</p><p>The holder map, the status bodies, and optionally a pyramid to replace the generation one.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>GenerationScheduler</code>&lt;<code>TChunk</code>&gt;</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="generate" tabindex="-1">generate() <a class="header-anchor" href="#generate" aria-label="Permalink to “generate()”">​</a></h3><blockquote><p><strong>generate</strong>(<code>chunkX</code>, <code>chunkZ</code>, <code>target</code>): <code>Promise</code>&lt;<code>TChunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/7418be10dd694d6bb5f284896ea80cab1efdb551/packages/chunkgen/src/GenerationScheduler.ts#L99" target="_blank" rel="noreferrer">GenerationScheduler.ts:99</a></p><p>Brings one chunk to a status, bringing its neighborhood to that status&#39;s dependencies first.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><h5 id="chunkz" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><h5 id="target" tabindex="-1">target <a class="header-anchor" href="#target" aria-label="Permalink to “target”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>TChunk</code>&gt;</p><p>The chunk at <code>target</code>. It is the live chunk the holder owns, so a later run that drives it further changes the same object.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>MissingGenerationLayerError when the step table leaves a layer below the target without a radius.</p><hr><h3 id="layersfor" tabindex="-1">layersFor() <a class="header-anchor" href="#layersfor" aria-label="Permalink to “layersFor()”">​</a></h3><blockquote><p><strong>layersFor</strong>(<code>target</code>): readonly (readonly [<code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code>, <code>number</code>])[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/7418be10dd694d6bb5f284896ea80cab1efdb551/packages/chunkgen/src/GenerationScheduler.ts#L84" target="_blank" rel="noreferrer">GenerationScheduler.ts:84</a></p><p>The layers a run walks for a target, from <code>empty</code> up to the target itself.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="target-1" tabindex="-1">target <a class="header-anchor" href="#target-1" aria-label="Permalink to “target”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p>readonly (readonly [<code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code>, <code>number</code>])[]</p><p>One entry per status, in ladder order, with the radius in chunks of the square that layer applies its step to.</p>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};